  app.post("/api/campaigns", async (req, res) => {
    try {
      if (!req.isAuthenticated()) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      // Calculate total chapters based on campaign length selection
      const campaignLength = req.body.campaignLength || 'standard';
      let totalChapters: number;
      
      switch (campaignLength) {
        case 'quick':
          totalChapters = 3; // Quick Adventure: 3 chapters (~30 min)
          break;
        case 'epic':
          totalChapters = 8 + Math.floor(Math.random() * 3); // 8, 9, or 10
          break;
        case 'legendary':
          totalChapters = 12 + Math.floor(Math.random() * 4); // 12, 13, 14, or 15
          break;
        case 'standard':
        default:
          totalChapters = 5 + Math.floor(Math.random() * 2); // 5 or 6
          break;
      }
      
      // Remove any client-provided totalChapters to ensure server controls chapter count
      const { totalChapters: _ignored, ...bodyWithoutChapters } = req.body;
      
      console.log(`Creating campaign with length: ${campaignLength}, totalChapters: ${totalChapters}`);
      
      const campaignData = insertCampaignSchema.parse({
        ...bodyWithoutChapters,
        userId: req.user.id,
        createdAt: new Date().toISOString(),
        currentSession: 1,
        totalChapters,
        isPublished: false,
        isPrivate: true,
        maxPlayers: 6,
        narrativeLog: bodyWithoutChapters.narrativeLog || { entries: [], chapterAdvances: [], xpAwards: [], foreclosedOptions: [] },
      });
      
      const campaign = await storage.createCampaign(campaignData);
      
      // Wire doctrine from generated CAML 2.0 content into campaign
      const generatedContent = req.body.generatedContent;
      if (generatedContent?.caml2?.doctrine || generatedContent?.doctrine) {
        const camlDoctrine = generatedContent.caml2?.doctrine || generatedContent.doctrine;
        const doctrineUpdate: any = {};
        if (camlDoctrine.campaign_question) {
          doctrineUpdate.campaignQuestion = camlDoctrine.campaign_question;
        }
        if (camlDoctrine.stakes && Array.isArray(camlDoctrine.stakes) && camlDoctrine.stakes.length > 0) {
          doctrineUpdate.campaignStakes = camlDoctrine.stakes;
        }
        if (Object.keys(doctrineUpdate).length > 0) {
          await storage.updateCampaign(campaign.id, doctrineUpdate);
          console.log(`[Campaign Create] Wired CAML doctrine: question="${doctrineUpdate.campaignQuestion?.substring(0, 50)}...", ${doctrineUpdate.campaignStakes?.length || 0} stakes`);
        }
      }
      
      // Wire CAML2 Adventure Skeleton data from generated content
      const caml2Update: any = {};
      const gc = req.body.generatedContent || req.body;
      
      if (gc.villainModel) {
        caml2Update.villainModel = gc.villainModel;
        console.log(`[Campaign Create] CAML2 Villain: ${gc.villainModel.name} (${gc.villainModel.archetype})`);
      }
      if (gc.framingEvent) {
        caml2Update.framingEvent = gc.framingEvent;
        console.log(`[Campaign Create] CAML2 Framing Event: ${gc.framingEvent.type}`);
      }
      if (gc.complicationsQueue) {
        caml2Update.complicationsQueue = gc.complicationsQueue;
        const qCount = (gc.complicationsQueue.moralQuandaries?.length || 0) + (gc.complicationsQueue.twists?.length || 0);
        console.log(`[Campaign Create] CAML2 Complications Queue: ${qCount} items`);
      }
      if (gc.encounterDesigns && Array.isArray(gc.encounterDesigns)) {
        caml2Update.encounterDesigns = gc.encounterDesigns;
        console.log(`[Campaign Create] CAML2 Encounters: ${gc.encounterDesigns.length} designed`);
      }
      if (gc.partyGoal) {
        caml2Update.partyGoal = gc.partyGoal;
        console.log(`[Campaign Create] CAML2 Party Goal: ${gc.partyGoal.primary?.substring(0, 50)}...`);
      }
      if (gc.powerNetwork) {
        caml2Update.powerNetwork = gc.powerNetwork;
        console.log(`[Campaign Create] CAML2 Power Network: ${gc.powerNetwork.groups?.length || 0} groups, ${gc.powerNetwork.consequenceChains?.length || 0} chains`);
      }
      if (gc.rivalAgent) {
        caml2Update.rivalAgent = gc.rivalAgent;
        console.log(`[Campaign Create] CAML2 Rival Agent: ${gc.rivalAgent.name || gc.rivalAgent.id}`);
      }
      if (gc.meterWorldEffects) {
        caml2Update.meterWorldEffects = gc.meterWorldEffects;
        console.log(`[Campaign Create] CAML2 Meter Effects: ${gc.meterWorldEffects.length || 0} meters mapped`);
      }
      if (gc.dynamicClimax) {
        caml2Update.dynamicClimax = gc.dynamicClimax;
        console.log(`[Campaign Create] CAML2 Dynamic Climax: ${gc.dynamicClimax.variations?.length || 0} variations`);
      }
      
      if (Object.keys(caml2Update).length > 0) {
        await storage.updateCampaign(campaign.id, caml2Update);
        console.log(`[Campaign Create] Wired ${Object.keys(caml2Update).length} CAML2 adventure skeleton fields`);
      }
      
      // Add the creator as a DM participant if a characterId is provided
      if (req.body.characterId) {
        await storage.addCampaignParticipant({
          campaignId: campaign.id,
          userId: req.user.id,
          characterId: req.body.characterId,
          role: 'dm',
          joinedAt: new Date().toISOString()
        });
      }
      
      // Add selected assets to the campaign if provided
      const selectedAssets = req.body.selectedAssets;
      if (selectedAssets) {
        // Add selected NPCs to campaign
        if (selectedAssets.npcs && Array.isArray(selectedAssets.npcs)) {
          for (const npcId of selectedAssets.npcs) {
            try {
              await storage.addNpcToCampaign({
                campaignId: campaign.id,
                npcId: npcId,
                role: 'companion',
                isActive: true,
                joinedAt: new Date().toISOString()
              });
            } catch (e) {
              console.log(`Failed to add NPC ${npcId} to campaign:`, e);
            }
          }
        }
        
        // Add selected quests to campaign  
        if (selectedAssets.quests && Array.isArray(selectedAssets.quests)) {
          for (const questId of selectedAssets.quests) {
            try {
              // Fetch the original quest from the quests table
              const [originalQuest] = await db.select().from(quests).where(eq(quests.id, questId));
              if (originalQuest) {
                await storage.createCampaignQuest({
                  campaignId: campaign.id,
                  title: originalQuest.title,
                  description: originalQuest.description,
                  status: 'active',
                });
              }
            } catch (e) {
              console.log(`Failed to add quest ${questId} to campaign:`, e);
            }
          }
        }
      }
      
      // Generate and create the initial session for this campaign
      try {
        // Generate initial narrative based on campaign description
        const { client: openaiClient, model: aiModel } = await getAIClient(req.user?.id);
        
        // CAML 2.0: Build state context if available for initial scene
        let initialStateContext = "";
        const campaignWorldState = campaign.worldState as any[] || [];
        const campaignNpcAttitudes = campaign.npcAttitudes as any[] || [];
        const campaignPressureMeters = campaign.pressureMeters as any[] || [];
        const campaignAvailablePaths = campaign.availablePaths as any[] || [];
        
        if (campaignWorldState.length > 0) {
          initialStateContext += "\n\nSTARTING WORLD STATE (introduce these naturally in the opening):\n";
          initialStateContext += campaignWorldState.map((s: any) => `- ${s.key}: ${s.value} (${s.description})`).join("\n");
        }
        
        if (campaignNpcAttitudes.length > 0) {
          initialStateContext += "\n\nKEY NPCs (introduce 1-2 in the opening, show their attitudes through behavior):\n";
          initialStateContext += campaignNpcAttitudes.map((npc: any) => 
            `- ${npc.name} (${npc.role}): attitude ${npc.attitude}/100, wants: ${npc.wants}`
          ).join("\n");
        }
        
        if (campaignPressureMeters.length > 0) {
          initialStateContext += "\n\nPRESSURE CLOCKS (hint at these tensions in the opening):\n";
          initialStateContext += campaignPressureMeters.map((m: any) => 
            `- ${m.name}: ${m.current}/${m.max} - ${m.consequence} if maxed`
          ).join("\n");
        }
        
        if (campaignAvailablePaths.length > 0) {
          initialStateContext += "\n\nMULTIPLE PATHS (hint that there are different approaches available):\n";
          initialStateContext += campaignAvailablePaths.map((p: any) => 
            `- ${p.approach}: ${p.description}`
          ).join("\n");
        }
        
        const mainHookContext = (campaign as any).mainHook ? `\nCAMPAIGN MAIN HOOK: "${(campaign as any).mainHook}"\nThis is the central premise driving the entire campaign. Every chapter and scene should connect back to this hook. Introduce it naturally in the opening scene.` : '';
        
        const prompt = `
You are an expert Dungeon Master using STATE-FIRST storytelling (CAML principles).
Campaign: ${campaign.title}. ${campaign.description || ""}
Difficulty level: ${campaign.difficulty || "Normal - Balanced Challenge"}
Narrative Style: ${campaign.narrativeStyle || "descriptive"}
${mainHookContext}
${initialStateContext}

CAML STORYTELLING PRINCIPLES:
1. This world is REACTIVE - state facts will change based on player actions
2. NPCs are DECISION-MAKERS with attitudes that affect what they reveal or block
3. FAILURE CHANGES THE WORLD - never just "try again", consequences matter
4. Multiple paths exist - hint that players have choices in how to approach problems
5. Pressure builds over time - introduce the sense of urgency naturally

DM PHILOSOPHY: You are a facilitator rooting for the player's success, not an adversary. Use the "yes, and..." approach to player creativity. Create cinematic descriptions using all five senses. Make NPCs feel real with their own motivations.

${SCENE_GENERATION_CONSTRAINTS}

${SCENE_CHOICE_FRAMING}

Generate the opening scene for this campaign. The opening should be an EXPLORATION or DISCOVERY scene, not combat.
The opening should:
- Establish the current world state naturally (show, don't tell)
- Introduce 1-2 key NPCs whose attitudes will matter
- Hint at the pressure/stakes without overwhelming
- Present choices that suggest multiple viable approaches exist

Include:
1. A descriptive narrative of the initial setting and situation (2-3 paragraphs, keep it concise)
2. A title for this opening scene  
3. A sceneType from: Exploration, Social, Discovery, Travel, Puzzle, Downtime (NOT Combat for openings)
4. Four possible actions the players can take next, with varied resolution modes (Dialogue, Investigation, Ingenuity, Stealth, not just Violence)
5. Initial quests/objectives for the players to complete

Return your response as a JSON object with these fields:
- narrative: The descriptive text of the opening scene (keep under 150 words). Naturally show the world state through environmental details and NPC behavior.
- sessionTitle: A short, engaging title for this scene
- location: The current location or setting where the campaign begins
- choices: An array of 4 objects. If the narrative presents a moral dilemma or decision fork, at least 2 choices MUST represent opposing sides of that decision — do NOT replace them with generic utility actions. Each with:
  - action: A short description of a possible action
  - description: A brief explanation of what this action entails 
  - requiresDiceRoll: Boolean indicating if this action requires a dice roll
  - diceType: If requiresDiceRoll is true, include the type of dice to roll ("d20" for most skill checks)
  - rollDC: If requiresDiceRoll is true, include the DC/difficulty (number to beat) for this roll
  - skillType: The skill or ability used (e.g., "perception", "persuasion", "stealth", "athletics", "investigation", "arcana", "insight"). IMPORTANT: Vary the skills used - social skills for NPC interactions, mental skills for investigation, physical skills as appropriate.
  - rollPurpose: A short explanation of what the roll is for (e.g., "Perception Check", "Persuasion Check", "Investigation Check")
  - successText: Brief text to display on a successful roll
  - failureText: Brief text describing a meaningful consequence (world changes, NPC reacts, opportunity shifts) - NOT just "you fail"
- activeQuests: An array of 1-3 initial quests, each with:
  - id: Unique identifier like "quest_main_1" or "quest_side_1"
  - title: Short quest title
  - description: What the player needs to accomplish
  - status: Always "active" for initial quests
  - xpReward: XP reward (100-500 based on difficulty)
`;
        
        const response = await openaiClient.chat.completions.create({
          model: aiModel,
          messages: [{ role: "user", content: prompt }],
          response_format: { type: "json_object" },
          max_tokens: 1500,
        });
        
        const responseContent = response.choices[0].message.content;
        let initialSessionData;
        
        try {
          initialSessionData = JSON.parse(responseContent);
          
          // Ensure the response has the expected structure
          if (!initialSessionData.narrative || !initialSessionData.sessionTitle || 
              !initialSessionData.location || !Array.isArray(initialSessionData.choices)) {
            throw new Error("Invalid response structure");
          }
          
          // Set default values for optional fields to prevent type errors
          initialSessionData.choices.forEach(choice => {
            if (choice.requiresDiceRoll) {
              choice.rollModifier = choice.rollModifier || 0;
            }
          });
          
          // Create initial session with quests in storyState
          const initialStoryState = {
            location: initialSessionData.location,
            activeNPCs: [],
            plotPoints: [],
            conditions: [],
            activeQuests: initialSessionData.activeQuests || [
              { id: "quest_main_1", title: "Begin the Adventure", description: "Explore your surroundings and discover the first clues", status: "active", xpReward: 100 }
            ]
          };
          
          const sessionData = {
            campaignId: campaign.id,
            sessionNumber: 1,
            title: initialSessionData.sessionTitle,
            narrative: initialSessionData.narrative,
            location: initialSessionData.location,
            choices: JSON.stringify(initialSessionData.choices),
            storyState: JSON.stringify(initialStoryState),
            sessionXpReward: 100,
            createdAt: new Date().toISOString(),
          };
          
          await storage.createCampaignSession(sessionData);
          console.log(`Created initial session for campaign ${campaign.id}`);
          
        } catch (parseError) {
          console.error("Failed to parse OpenAI response for initial session:", parseError);
          console.log("Raw response:", responseContent);
          
          // Create a fallback session if parsing fails
          const fallbackSessionData = {
            campaignId: campaign.id,
            sessionNumber: 1,
            title: "The Adventure Begins",
            narrative: "Your journey begins in a small settlement at the edge of the known world. The air is filled with possibility as you prepare to embark on your first adventure.",
            location: "Starting Village",
            choices: JSON.stringify([
              { action: "Visit the local tavern", description: "Gather information from the locals", requiresDiceRoll: false },
              { action: "Meet with the town elder", description: "Learn about problems facing the settlement", requiresDiceRoll: false },
              { action: "Investigate nearby ruins", description: "Search for treasure and adventure", requiresDiceRoll: true, diceType: "d20", rollDC: 12, rollModifier: 0, rollPurpose: "Investigation Check", successText: "You find something interesting!", failureText: "Nothing catches your eye." }
            ]),
            storyState: JSON.stringify({
              location: "Starting Village",
              activeNPCs: [],
              plotPoints: [],
              conditions: [],
              activeQuests: [
                { id: "quest_main_1", title: "Uncover the Mystery", description: "Explore the village and discover what adventure awaits", status: "active", xpReward: 100 }
              ]
            }),
            sessionXpReward: 100,
            createdAt: new Date().toISOString(),
          };
          
          await storage.createCampaignSession(fallbackSessionData);
          console.log(`Created fallback session for campaign ${campaign.id} due to parsing error`);
        }
        
        // Update the campaign with the session number to establish the link
        await storage.updateCampaignSession(campaign.id, 1);
        
        // Generate initial dungeon map for the campaign with theme awareness
        try {
          // Detect theme from campaign title and description
          const mapCampaignText = `${campaign.title || ''} ${campaign.description || ''}`.toLowerCase();
          
          // Theme-specific map configurations
          const mapThemes: Record<string, { 
            mapName: string; 
            wallType: string; 
            floorType: string; 
            corridorType: string;
            roomNames: string[];
            features: string[];
          }> = {
            nautical: {
              mapName: `${campaign.title} - Ship Layout`,
              wallType: 'hull',
              floorType: 'deck',
              corridorType: 'passage',
              roomNames: ['Main Deck', 'Cargo Hold', 'Captain\'s Quarters', 'Crew Quarters', 'Galley', 'Brig', 'Gun Deck', 'Storage Bay', 'Navigation Room', 'Armory'],
              features: ['barrel', 'crate', 'cannon', 'rope_coil', 'lantern', 'anchor', 'chest', 'hammock']
            },
            forest: {
              mapName: `${campaign.title} - Wilderness`,
              wallType: 'dense_trees',
              floorType: 'clearing',
              corridorType: 'path',
              roomNames: ['Forest Clearing', 'Ancient Grove', 'Hidden Glade', 'Stream Crossing', 'Hollow Tree', 'Druid Circle', 'Animal Den', 'Fairy Ring', 'Rocky Outcrop', 'Fallen Tree Bridge'],
              features: ['fallen_log', 'mushroom_circle', 'animal_tracks', 'wildflowers', 'berry_bush', 'bird_nest', 'stream']
            },
            urban: {
              mapName: `${campaign.title} - City District`,
              wallType: 'building',
              floorType: 'cobblestone',
              corridorType: 'alley',
              roomNames: ['Market Square', 'Tavern Back Room', 'Guild Hall', 'Warehouse', 'Noble\'s Parlor', 'Sewer Junction', 'Guard Post', 'Shop Interior', 'Cellar', 'Rooftop'],
              features: ['market_stall', 'barrel', 'crate', 'torch_sconce', 'bench', 'sewer_grate', 'poster']
            },
            dungeon: {
              mapName: `${campaign.title} - Dungeon`,
              wallType: 'wall',
              floorType: 'floor',
              corridorType: 'corridor',
              roomNames: ['Entrance Chamber', 'Guard Room', 'Treasure Vault', 'Ritual Chamber', 'Prison Cells', 'Armory', 'Throne Room', 'Crypt', 'Library', 'Alchemy Lab'],
              features: ['pillar', 'statue', 'altar', 'chest', 'torch', 'debris', 'bones']
            }
          };
          
          // Detect which theme matches using weighted scoring
          const mapThemeKeywords: Record<string, string[]> = {
            nautical: ['ship', 'sea', 'ocean', 'pirate', 'sailor', 'nautical', 'harbor', 'coast', 'voyage'],
            forest: ['forest', 'wood', 'tree', 'grove', 'wilderness', 'druid', 'nature', 'woodland'],
            urban: ['city', 'town', 'urban', 'guild', 'tavern', 'sewer', 'street', 'market'],
          };
          let detectedMapTheme = 'dungeon';
          let mapBestScore = 0;
          for (const [theme, kws] of Object.entries(mapThemeKeywords)) {
            const score = kws.filter(kw => mapCampaignText.includes(kw)).length;
            if (score >= 2 && score > mapBestScore) { mapBestScore = score; detectedMapTheme = theme; }
          }
          
          const activeMapTheme = mapThemes[detectedMapTheme];
          console.log(`Generating ${detectedMapTheme}-themed map for campaign: ${campaign.title}`);
          
          const generateInitialDungeonMap = () => {
            const width = 25;
            const height = 18;
            const tiles: any[][] = [];
            
            for (let y = 0; y < height; y++) {
              const row: any[] = [];
              for (let x = 0; x < width; x++) {
                row.push({ type: activeMapTheme.wallType, explored: false, visible: false, theme: detectedMapTheme });
              }
              tiles.push(row);
            }
            
            const rooms: { x: number; y: number; w: number; h: number; name: string }[] = [];
            const numRooms = 5 + Math.floor(Math.random() * 4);
            const usedRoomNames = new Set<string>();
            
            for (let i = 0; i < numRooms; i++) {
              const roomW = 3 + Math.floor(Math.random() * 4);
              const roomH = 3 + Math.floor(Math.random() * 3);
              const roomX = 1 + Math.floor(Math.random() * (width - roomW - 2));
              const roomY = 1 + Math.floor(Math.random() * (height - roomH - 2));
              
              let overlaps = false;
              for (const room of rooms) {
                if (roomX < room.x + room.w + 1 && roomX + roomW + 1 > room.x &&
                    roomY < room.y + room.h + 1 && roomY + roomH + 1 > room.y) {
                  overlaps = true;
                  break;
                }
              }
              
              if (!overlaps) {
                // Pick a unique room name for this theme
                let roomName = activeMapTheme.roomNames[i % activeMapTheme.roomNames.length];
                let nameAttempt = 0;
                while (usedRoomNames.has(roomName) && nameAttempt < activeMapTheme.roomNames.length) {
                  roomName = activeMapTheme.roomNames[(i + nameAttempt + 1) % activeMapTheme.roomNames.length];
                  nameAttempt++;
                }
                usedRoomNames.add(roomName);
                
                rooms.push({ x: roomX, y: roomY, w: roomW, h: roomH, name: roomName });
                for (let ry = roomY; ry < roomY + roomH; ry++) {
                  for (let rx = roomX; rx < roomX + roomW; rx++) {
                    tiles[ry][rx] = { 
                      type: activeMapTheme.floorType, 
                      explored: false, 
                      visible: false, 
                      theme: detectedMapTheme,
                      roomName: roomName
                    };
                  }
                }
                
                // Add theme-appropriate features to some rooms
                if (Math.random() > 0.5 && activeMapTheme.features.length > 0) {
                  const featureX = roomX + Math.floor(roomW / 2);
                  const featureY = roomY + Math.floor(roomH / 2);
                  const feature = activeMapTheme.features[Math.floor(Math.random() * activeMapTheme.features.length)];
                  if (tiles[featureY] && tiles[featureY][featureX]) {
                    tiles[featureY][featureX].feature = feature;
                  }
                }
              }
            }
            
            for (let i = 1; i < rooms.length; i++) {
              const prev = rooms[i - 1];
              const curr = rooms[i];
              const prevCenterX = Math.floor(prev.x + prev.w / 2);
              const prevCenterY = Math.floor(prev.y + prev.h / 2);
              const currCenterX = Math.floor(curr.x + curr.w / 2);
              const currCenterY = Math.floor(curr.y + curr.h / 2);
              
              let x = prevCenterX;
              while (x !== currCenterX) {
                if (tiles[prevCenterY] && tiles[prevCenterY][x]) {
                  tiles[prevCenterY][x] = { type: activeMapTheme.corridorType, explored: false, visible: false, theme: detectedMapTheme };
                }
                x += x < currCenterX ? 1 : -1;
              }
              let y = prevCenterY;
              while (y !== currCenterY) {
                if (tiles[y] && tiles[y][currCenterX]) {
                  tiles[y][currCenterX] = { type: activeMapTheme.corridorType, explored: false, visible: false, theme: detectedMapTheme };
                }
                y += y < currCenterY ? 1 : -1;
              }
            }
            
            const entities: any[] = [];
            const playerPos = rooms.length > 0 
              ? { x: Math.floor(rooms[0].x + rooms[0].w / 2), y: Math.floor(rooms[0].y + rooms[0].h / 2) }
              : { x: 4, y: 4 };
            
            entities.push({ id: "player", type: "player", x: playerPos.x, y: playerPos.y, name: "Player" });
            
            for (let ry = Math.max(0, playerPos.y - 2); ry <= Math.min(height - 1, playerPos.y + 2); ry++) {
              for (let rx = Math.max(0, playerPos.x - 2); rx <= Math.min(width - 1, playerPos.x + 2); rx++) {
                const dist = Math.sqrt(Math.pow(rx - playerPos.x, 2) + Math.pow(ry - playerPos.y, 2));
                if (tiles[ry] && tiles[ry][rx] && dist <= 2) {
                  tiles[ry][rx].explored = true;
                  tiles[ry][rx].visible = dist <= 1.5;
                }
              }
            }
            
            return { 
              width, 
              height, 
              tiles, 
              entities, 
              playerPosition: playerPos, 
              name: activeMapTheme.mapName, 
              level: 1,
              theme: detectedMapTheme,
              rooms: rooms.map(r => ({ name: r.name, x: r.x, y: r.y, w: r.w, h: r.h }))
            };
          };
          
          const initialMapData = generateInitialDungeonMap();
          await storage.createCampaignDungeonMap({
            campaignId: campaign.id,
            mapName: activeMapTheme.mapName,
            mapData: initialMapData,
            playerPosition: initialMapData.playerPosition,
            fogOfWar: {},
            exploredTiles: [],
          });
          console.log(`Created initial ${detectedMapTheme}-themed map for campaign ${campaign.id}`);
        } catch (mapError) {
          console.error("Failed to create initial dungeon map:", mapError);
        }
        
      } catch (sessionError) {
        console.error("Error creating initial session:", sessionError);
        
        // Create a fallback session if OpenAI call fails
        const fallbackSessionData = {
          campaignId: campaign.id,
          sessionNumber: 1,
          title: "The Adventure Begins",
          narrative: "Your journey begins in a small settlement at the edge of the known world. The air is filled with possibility as you prepare to embark on your first adventure.",
          location: "Starting Village",
          choices: JSON.stringify([
            { action: "Visit the local tavern", description: "Gather information from the locals", requiresDiceRoll: false },
            { action: "Meet with the town elder", description: "Learn about problems facing the settlement", requiresDiceRoll: false },
            { action: "Investigate nearby ruins", description: "Search for treasure and adventure", requiresDiceRoll: true, diceType: "d20", rollDC: 12, rollModifier: 0, rollPurpose: "Investigation Check", successText: "You find something interesting!", failureText: "Nothing catches your eye." }
          ]),
          storyState: JSON.stringify({
            location: "Starting Village",
            activeNPCs: [],
            plotPoints: [],
            conditions: [],
            activeQuests: [
              { id: "quest_main_1", title: "Uncover the Mystery", description: "Explore the village and discover what adventure awaits", status: "active", xpReward: 100 }
            ]
          }),
          sessionXpReward: 100,
          createdAt: new Date().toISOString(),
        };
        
        try {
          await storage.createCampaignSession(fallbackSessionData);
          console.log(`Created fallback session for campaign ${campaign.id} due to API error`);
          
          // Update the campaign with the session number to establish the link
          await storage.updateCampaignSession(campaign.id, 1);
        } catch (fallbackError) {
          console.error("Failed to create fallback session:", fallbackError);
        }
      }
      
      res.status(201).json(campaign);
    } catch (error) {
      if (error instanceof z.ZodError) {
        res.status(400).json({ message: "Invalid campaign data", errors: error.errors });
      } else {
        console.error("Error creating campaign:", error);
        res.status(500).json({ message: "Failed to create campaign" });
      }
    }
  });

  app.get("/api/campaigns/:id", async (req, res) => {
    try {
      if (!req.isAuthenticated()) {
        return res.status(401).json({ message: "Not authenticated" });
      }
      
      const id = parseInt(req.params.id);
      const campaign = await storage.getCampaign(id);
      
      if (!campaign) {
        return res.status(404).json({ message: "Campaign not found" });
      }
      
      // Check if user is authorized to view this campaign
      const participants = await storage.getCampaignParticipants(id);
      const isParticipant = participants.some(p => p.userId === req.user.id);
      
      if (campaign.userId !== req.user.id && !isParticipant) {
        return res.status(403).json({ message: "Not authorized to view this campaign" });
      }
      
      // Get character details for each participant
      const participantsWithDetails = await Promise.all(
        participants.map(async (p) => {
          const character = await storage.getCharacter(p.characterId);
          const user = await storage.getUser(p.userId);
          return {
            ...p,
            character: character,
            username: user ? user.username : 'Unknown',
            displayName: user ? user.displayName : null
          };
        })
      );
      
      const campaignWithParticipants = {
        ...campaign,
        participants: participantsWithDetails
      };
      
      res.json(campaignWithParticipants);
    } catch (error) {
      console.error("Error fetching campaign:", error);
      res.status(500).json({ message: "Failed to fetch campaign" });
    }
  });

